; ---- the RPSP slot (Y:STBASE + x:$418, $20 words): the render's stereo ring first (2 x BL
; words, L and R interleaved -- ring slot m is words 2m (L) and 2m+1 (R) -- modulo-addressed,
; so it starts the slot), then the state. r6 rests on RF through a pass.
                        ;  the next output interval, 0 <= tau < PSP; bit 23 set = it ticks there)

zqrp:
        move    y:>$40,a
        and     #<3,a                   ; the mode (Z from bits 47-24, a1)
        beq     zqstk                   ; RPCH: stock, untouched
        move    a1,n1                   ; n1 = mode
        move    y:>$a7f,a
        cmp     #>$f2e5c5,a
        beq     zqtok
        bsr     zqinit                  ; first use on this core (or a new build)
zqtok:
; ---- a trig (rev 14). The engines read the ring BEHIND the OT's position, and
; at a trig the frames behind the new sound hold stale audio (the last voice's,
; unscaled -- its AMP silenced it later in the chain). Stock reads only floor(p)
; and floor(p)+1; RPS9/RPSP would replay 8-13 frames of it at the new trig's
; full AMP: the crack at every trig start (user, rev 13; measured in ot_emu).
; So at the pass that starts the new sound, the 16 frames before its first
; frame become silence, and RPSP's slot starts clean (tag cleared: zqsp).
        move    x:>$419,r4              ; this track's unpacked per-voice record
        move    m1,n5                   ; restored at zqdone
        move    x:(r4+$1e),a            ; its word +$1E (m4 is linear: x:$419 + $1E can
        move    #$7f,m1                 ;  straddle a 128-word block)
        jclr    #12,a1,zqnh             ; a trig starts in this frame?
        move    lc,b                    ; ... and this is the frame's second pass (the
        cmp     #<1,b                   ; voice module's `do #2`: LC 2, then 1), where
        bne     zqnh                    ; the new sound starts. (Not a count of visits:
                                        ; an empty first pass carries mode 0 and never
                                        ; reaches this code -- rev 14 missed every trig
                                        ; landing on a frame boundary that way.)
        move    x:(r5),a                ; the new sound's first frame (ring word offset)
        move    x:>$418,n6              ; the track offset
        sub     #<32,a
        and     #>$7e,a
        move    a1,n2
        move    #>$a1b,r6
        lua     (r2)+n2,r1              ; (r2 is 128-aligned: r1 stays in the ring,
        clr     a                       ;  and m1 = $7f wraps it)
        do      #<32,zqnr               ; (a DO, not a REP: interruptible, as octabam's)
        move    a,x:(r1)+
zqnr:
        move    a,y:(r6+n6)             ; RPSP: a clean slot at zqsp
zqnh:
        jclr    #0,n1,zqsp              ; mode 2: RPSP (1 and 3: RPS9)

; ============================================================ RPS9 (Akai)
; output i = 12-bit(virtual ADC at p_i - c - 1): a 16-tap polyphase kernel over
; ring frames k_i-2c-1 .. k_i, all delivered. (NOT k_i+1: at a zero fraction
; the OT does not deliver it -- the stock kernel weights it 0. Measured.)
        move    #<$62,n2
        move    #>$fff000,y1            ; the 12-bit mask
        lua     (r2)+n2,r6              ; r6 = r2 + the first tap's offset (in the block)
        move    #<32,n7                 ; the table is transposed: tap t of phase p at R9TAB + 32 t + p
        move    y:(r5),b                ; b1 = the fraction (each output loads the next one's)
        do      r7,zq9e
        move    x:(r5)+,n1              ; n1 = ring word offset of k_i
        move    r6,r1
        lsr     #19,b                   ; phase 0..31
        move    (r1)+n1                 ; r1 = the first tap, k_i - 2c - 1 (m1 = $7f wraps it)
        add     #>$c00,b
        move    b1,r7                   ; the phase's tap 0 (the loop count is in LC now)
        clr     a       x:(r1)+,x0
        clr     b       x:(r1)+,x1      y:(r7)+n7,y0
; taps 1..15, unrolled (rev 17): a DO here cost 5 cycles per output, 8% of RPS9
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a x:(r1)+,x0
        mac     x1,y0,b x:(r1)+,x1      y:(r7)+n7,y0
        mac     y0,x0,a
        mac     x1,y0,b a,x0            ; limit L
        tfr     x0,a    b,x0            ; limit R
        and     y1,a    x0,b            ; 12 bits: floor to a 1/2048 step
        and     y1,b    a1,x:(r3)+
        move    b,x:(r3)+       y:(r5),b        ; (b = b1: in range); the next fraction
zq9e:
        move    n5,m1                   ; (zqdone's tail, inline: no branch)
        move    #$0,r7
        move    x:(r5),n6
        move    y:(r5)+,a
        rts

; ============================================================ RPSP (SP-1200)
; Full stereo (2026-10-15): L and R each go through the SP -- the virtual ADC (8 taps) at
; the SP's clock, 12 bits, the band-limited render to 44.1 kHz -- out raw, as the SP's
; outputs 7/8. One clock, one tick schedule, one trig handling for both. The SP's clock
; period is 1.69 output samples, so an output interval holds at most one tick. A tick
; at u stores a new step per channel; the render spreads it over this and the next L-1
; outputs with the band-limited step response. The ring is in "full form": a slot holds
; what its output will be, / 4 (the held step when the slot was last read, plus every
; later tick's share), so an output is 4 x its slot and the slot is then reset to the
; current held step / 4 (repitch_engine_model.DspExact: the rev 13 render, to the bit).
zqsp:
        move    r7,b                    ; an empty pass: nothing to render, and x:(r5)
        tst     b                       ; is not this track's -- the slot waits for a
        beq     zqdone                  ; real pass (on the unit an empty pass is mode 0)
        move    x:>$418,n6              ; the track offset
        move    #>$a14,r6
        move    r7,n2                   ; n2 = the pass count
        move    (r6)+n6                 ; r6 = this track's RF (m6 = $7f: the slot does
        move    #$40,r4                 ;  not straddle 128 words)
        move    y:(r6+$7),b
        cmp     #>$5a5a0a,b
        beq     zqsok
        clr     b                       ; stale, first use or a trig: a clean slot
        lua     (r6-$14),r1            ; (the ring starts the slot)
        move    #>$5a5a0a,x1
        move    #>$800000,x0            ; tau = 0, held as tau - 1
        move    r1,y:(r6+$6)
        do      #$14,zqsz
        move    b,y:(r1)+
zqsz:
        move    b,y:(r6+$1)
        move    b,y:(r6+$3)
        move    b,y:(r6+$4)
        move    x0,y:(r6+$5)
        move    x1,y:(r6+$7)
zqsok:
; ---- this pass's constants. r = int(r) + frac(r) as the DSP holds it (x:$40 is read
; for bit 0 only -- on the unit it reads $c1 at 1.0x; the table builder masks it too,
; measured in ot_emu -- and y:$40 carries the mode tag in its low bits, as the twin's r
; does): RF = frac(r); RH = r x 2^23, unsigned (the tick's (u - 1) r)
        move    l:(r4),a                ; a = l:$40 = r as 24.24 (r4 = $40)
        and     #<1,a                   ; (a1 only; a0 stays)
        move    a0,y:(r6)               ; RF
        asr     a                       ; a0 = RH (a1 = 0)
        move    a0,y:(r6+$2)
        move    m7,n7                   ; restored at zqoe
        move    #$13,m7
        move    y:(r6+$6),r7
        move    y:(r6+$5),r4         ; r4 = tau - 1 through the pass; n4 = one interval
        move    #>$800000,n4            ;  (+2^23 = -2^23, mod 2^24)
        move    #<$3,n6              ; the tick's walk of r6 ends with (r6)-n6
        move    y:(r6+$3),y0         ; y0, y1 = the held steps / 4 (the out block's)
        move    y:(r6+$4),y1
        move    y:(r7)+,a               ; a, b = the first output's L and R slots
        move    y:(r7)-,b
        do      n2,zqoe
        jclr    #23,r4,zqout            ; tau >= 1 (tau < PSP < 2 always): no tick here
; ---- a tick at u = tau. r6 walks RF PHI RH H4L H4R and back; r5 is the ADC's table
; pointer (the output table parked in n1), r1 the ADC's ring pointer, then the render's.
        move    y:(r6)+,x0              ; RF
        move    y:(r6),a                ; phi
        add     x0,a    r4,x1           ; phi + RF ; x1 = u - 1 (Q23, signed)
        lsr     a       a1,y:(r6)+      ; phi = frac(phi + RF) ; a1 = phi / 2 (Q23)
        move    y:(r6)+,x0              ; RH
        mpysu   x1,x0,b                 ; (u - 1) RH x 2: (u - 1) r x 2^47
        move    a1,x0
        mpyi    #>$6c6152,x0,a             ; (PSP/2) phi x 2: the SP's truncating read shift
        asr     #23,b,b                 ; (u - 1) r, 24.24 frames (floored)
        asr     #22,a,a                 ; the shift, 24.24 frames
        sub     a,b     x:(r5),a        ; b = (u - 1) r - shift ; a = this output's ring words
        asr     a       r5,n1           ; -> frames (even: a0 = 0) ; the output table parked
        move    y:(r5),a0               ; + its fraction: p_i
        add     b,a     (r7)-           ; pos = p_i - (1 - u) r - shift ; r7 -> R(i+9), where
        move    a0,b                    ;  the render's walk down starts ; b1 = frac(pos)
        asl     a                       ; frames -> words (the fraction's top bit in bit 0)
        sub     #<$e,a                ; first tap = floor(pos) - 2c - 1
        and     #>$7e,a                 ; (the mask drops bit 0)
        lsr     #19,b                   ; phase 0..31
        move    a1,n2
        lsl     #3,b                    ; x 8 taps
        lua     (r2)+n2,r1              ; (r2 is 128-aligned: m1 = $7f wraps r1 in the ring)
        add     #>$a80,b
        move    b1,r5                   ; the phase's row
; ---- the virtual ADC, both channels: 8 taps over L (a) and R (b)
        move    x:(r1)+,x0
        move    y:(r5)+,y0
        mpy     y0,x0,a x:(r1)+,x1
        mpy     x1,y0,b x:(r1)+,x0      y:(r5)+,y0
        mac     y0,x0,a x:(r1)+,x1
        mac     x1,y0,b x:(r1)+,x0      y:(r5)+,y0
        mac     y0,x0,a x:(r1)+,x1
        mac     x1,y0,b x:(r1)+,x0      y:(r5)+,y0
        mac     y0,x0,a x:(r1)+,x1
        mac     x1,y0,b x:(r1)+,x0      y:(r5)+,y0
        mac     y0,x0,a x:(r1)+,x1
        mac     x1,y0,b x:(r1)+,x0      y:(r5)+,y0
        mac     y0,x0,a x:(r1)+,x1
        mac     x1,y0,b x:(r1)+,x0      y:(r5)+,y0
        mac     y0,x0,a x:(r1)+,x1
        mac     x1,y0,b x:(r1)+,x0      y:(r5)+,y0
        mac     y0,x0,a x:(r1)+,x1
        mac     x1,y0,b a,x0            ; x0 = L (limited)
; ---- the steps: 12 bits, / 4 (exact) = the new held steps, stored; dh = (new - old) / 2.
; The render's row j = floor(uR) and fraction frac(uR), both from u - 1 (R = 16): its
; bits 23..19 are 16 + j, so (u - 1) >> 14 (arithmetic) & $fe0 = $E00 + 32 j = BTAB + BROW j
        tfr     x0,a    b,x1            ; a = L ; x1 = R (limited)
        and     #>$fff000,a             ; L, 12 bits
        asr     #2,a,a                  ; / 4
        tfr     x1,b    y:(r6),y0       ; b = R ; y0 = the old H4L
        sub     y0,a    a,y:(r6)+       ; a = H4L' - H4L ; H4L' stored
        and     #>$fff000,b
        asr     #2,b,b
        sub     y1,b    b,y:(r6)        ; b = H4R' - H4R ; H4R' stored
        asl     a       r4,x1           ; a = dhL = the step / 2 ; x1 = u - 1
        asl     b       a,y0            ; b = dhR ; y0 = dhL
        tfr     x1,a    b,y1            ; a = u - 1 ; y1 = dhR
        asr     #14,a,b
        add     #>$d8c2a8,a              ; tau += PSP (the out block takes this interval)
        and     #>$fe0,b                ; b1 = row j
        tfr     x1,a    a1,r4           ; a = u - 1 ; r4 = tau - 1
        lsl     #5,a
        lsr     a       b1,r1           ; a1 = frac(uR), Q23 ; r1 = row j: its L (T', D) pairs,
        move    a1,x0                   ;  in the order they are applied (tap L-1 first)
        move    y:(r1)+,a               ; T'
        move    y:(r1)+,x1              ; D
        mac     x1,x0,a n1,r5           ; a = w = T' + frac D: the step response / 2 ; r5 back
; ---- the render, unrolled: taps L-1 .. 0 (ring slots i+9 .. i, walked down, R then L)
        move    a,x1    y:(r7),b        ; x1 = w ; b = the slot's R
        mac     y1,x1,b y:(r1)+,a       ; b += dhR w ; next T'
        move    b,y:(r7)-
        move    y:(r7),b                ; the slot's L
        mac     x1,y0,b y:(r1)+,x1      ; b += dhL w ; next D
        mac     x1,x0,a b,y:(r7)-       ; next w
        move    a,x1    y:(r7),b
        mac     y1,x1,b y:(r1)+,a
        move    b,y:(r7)-
        move    y:(r7),b
        mac     x1,y0,b y:(r1)+,x1
        mac     x1,x0,a b,y:(r7)-
        move    a,x1    y:(r7),b
        mac     y1,x1,b y:(r1)+,a
        move    b,y:(r7)-
        move    y:(r7),b
        mac     x1,y0,b y:(r1)+,x1
        mac     x1,x0,a b,y:(r7)-
        move    a,x1    y:(r7),b
        mac     y1,x1,b y:(r1)+,a
        move    b,y:(r7)-
        move    y:(r7),b
        mac     x1,y0,b y:(r1)+,x1
        mac     x1,x0,a b,y:(r7)-
        move    a,x1    y:(r7),b
        mac     y1,x1,b y:(r1)+,a
        move    b,y:(r7)-
        move    y:(r7),b
        mac     x1,y0,b y:(r1)+,x1
        mac     x1,x0,a b,y:(r7)-
        move    a,x1    y:(r7),b
        mac     y1,x1,b y:(r1)+,a
        move    b,y:(r7)-
        move    y:(r7),b
        mac     x1,y0,b y:(r1)+,x1
        mac     x1,x0,a b,y:(r7)-
        move    a,x1    y:(r7),b
        mac     y1,x1,b y:(r1)+,a
        move    b,y:(r7)-
        move    y:(r7),b
        mac     x1,y0,b y:(r1)+,x1
        mac     x1,x0,a b,y:(r7)-
        move    a,x1    y:(r7),b
        mac     y1,x1,b y:(r1)+,a
        move    b,y:(r7)-
        move    y:(r7),b
        mac     x1,y0,b y:(r1)+,x1
        mac     x1,x0,a b,y:(r7)-
        move    a,x1    y:(r7),b
        mac     y1,x1,b y:(r1)+,a
        move    b,y:(r7)-
        move    y:(r7),b
        mac     x1,y0,b y:(r1)+,x1
        mac     x1,x0,a b,y:(r7)-
; tap 0 (this output's slot): R and L stay in b and a, unstored, for the out block (which
; resets the slot); y0, y1 back to the held steps / 4; r6 back on RF
        move    a,x1    y:(r7)-,b       ; r7 = this output's L
        mac     y1,x1,b y:(r6)-,y1      ; b = the slot's R ; y1 = H4R'
        move    y:(r7),a
        mac     x1,y0,a y:(r6)-n6,y0    ; a = the slot's L ; y0 = H4L'
; ---- out: 4 x the slot (limited); the slot := the held steps / 4. a, b = this output's L
; and R slots on entry (read ahead at the end of the last output, or the tick's own)
zqout:
        asl     a       y0,y:(r7)+      ; L slot := H4L
        asl     a       y1,y:(r7)+      ; R slot := H4R ; a = 4 x L
        asl     b       a,x:(r3)+       y:(r7)+,a       ; out L ; a = the next output's L slot
        asl     b       (r4)+n4         ; b = 4 x R ; tau -= one interval
        move    b,x:(r3)+       y:(r7)-,b       ; out R ; b = the next R slot (r7 on its L)
        move    (r5)+                   ; the next output's table entry
zqoe:
        move    r7,y:(r6+$6)
        move    r4,y:(r6+$5)
        move    n7,m7

zqdone:
        move    n5,m1
        move    #$0,r7                  ; the stock kernel's `do r7` skips
zqstk:
        move    x:(r5),n6               ; displaced from the hook site
        move    y:(r5)+,a
        rts

; ---------------------------------------------------------------------------
; zqboot (rev 17): the table copy at boot, outside every audio pass (the KYOTI
; load audit: on a core's first RPS9/RPSP pass it cost one frame ~5,000
; instructions on top of its audio). Hooked at the payload's one-time memory
; clear, before its frame loop exists: A P:0x46 / B P:0x47, `do b,LA` with
; a = 0, b = the count, r4/r5 its two pointers. This runs the clear's passes
; but the last; the stock body at the return address runs that one, so the
; memory the clear leaves is stock's (an extra pass would write one word past
; each run -- on payload A, Y:$38000, payload B's entry in the shared window).
; Then zqinit, with the registers it uses kept on the hardware stack. zqrp's
; tag check stays: it rebuilds Y if anything ever overwrites the tables. (Placed
; before zqinit: octabam's dsp_asm sizes a backward call differently per pass.)
zqboot:
        move    #>1,x0
        sub     x0,b
        do      b,zqbz
        move    a,y:(r4)+
        move    a,y:(r5)+
zqbz:
        add     x0,b                    ; the count, as the stock DO leaves it
        move    b1,ssh                  ; the registers zqinit uses, on the hardware
        move    r1,ssh                  ; stack (the boot path is shallow: jsr + five +
        move    r4,ssh                  ; bsr + one DO)
        move    n2,ssh
        move    n4,ssh
        bsr     zqinit
        move    ssh,n4
        move    ssh,n2
        move    ssh,r4
        move    ssh,r1
        move    ssh,b
        clr     a
        rts

; ---------------------------------------------------------------------------
; zqinit: copy the tables into Y (first use on a core, or a new build). The
; virtual-ADC tables arrive as their 16 stored half-rows; the render as T'[0..LR/2]
; (T' = T + 1/2 = (1 - Gc) / 2, the step response / 2: SP12 stereo's full-form ring).
; Preserves r5 and r7 (hardware stack: one bsr and one DO below zqrp).
zqinit:
        move    r7,n2
        move    #>$fab1e0,r1             ; block 1: the render's half-table
        move    #>$c00,r4               ; T'[0..LR] into a scratch run first (RPS9's
        move    #>$ca0,r7              ;  table's place: that table is copied last)
        move    #>$400000,y0            ; 1/2
        do      #$51,zqi3             ; T'[k] stored for k = 0..LR/2; T'[LR-k] = 1/2 - T'[k]
        move    p:(r1)+,x0
        move    x0,y:(r4)+
        move    y0,a
        sub     x0,a
        move    a1,y:(r7)-
zqi3:
; the render's table: row j (one per segment) holds the L taps' (T'[k], D[k] = T'[k+1] -
; T'[k]) pairs in the order a tick applies them, tap L-1 first: pair i is tap L-1-i, at
; segment k = iR + j, so a tick walks one row with (r1)+; rows are BROW words apart. One
; DO (the hardware stack's budget): every L pairs the next row starts one segment up.
        move    #>$e00,r1
        move    #>$c00,r7               ; row 0, pair 0: T'[0]
        move    r7,r4
        move    #>$f,n4             ; k+1 -> k+R (n1 holds zqrp's mode)
        move    #>$a,b
        do      #$a0,zqi4
        move    y:(r4)+,x0              ; T'[k]
        move    y:(r4)+n4,a             ; T'[k+1]
        sub     x0,a    x0,y:(r1)+
        move    a1,y:(r1)+
        sub     #<1,b
        bne     zqi5
        move    (r7)+
        lua     (r1+$c),r1            ; past the row's padding
        move    r7,r4
        move    #>$a,b
zqi5:
        nop                             ; (the loop's last word: a branch target)
zqi4:
; the virtual-ADC tables: row 31-ph is row ph reversed, so one forward pass writes row
; ph going up and its mirror going down from the table's end (rev 12's copy)
        move    #>$fab2e0,r1            ; block 2: the RPSP half-rows; the RPS9 rows follow
        move    #>$a80,r4
        move    #>$b7f,r7
        do      #$80,zqi1
        move    p:(r1)+,x0
        move    x0,y:(r4)+
        move    x0,y:(r7)-
zqi1:
; RPS9's arrives tap-major (16 runs, one per tap, of phases 0..15): each run goes up
; from the table's start and its mirror (phases 31..16 of tap 15-t) down from its end
        move    #>$c00,r4              ; r1 is at XR9: it follows XSP
        move    #>$dff,r7
        move    #>$10,b
        do      #$100,zqi2
        move    p:(r1)+,x0
        move    x0,y:(r4)+
        move    x0,y:(r7)-
        sub     #<1,b
        bne     zqi6
        lua     (r4+$10),r4           ; past the mirrored phases
        lua     (r7-$10),r7
        move    #>$10,b
zqi6:
        nop                             ; (the loop's last word: a branch target)
zqi2:
        move    #>$f2e5c5,x0
        move    x0,y:>$a7f
        move    n2,r7
        rts
